<?php
defined('ABSPATH') || exit;

final class TNet_Community_Topic_Composer_Controller {
    private const COMMUNITIES = ['community:local-demo' => 'Local Community Demo'];
    private const MODES = ['discussion'=>'Discussion','question'=>'Question','candle'=>'Candle (coming soon)','idea'=>'Idea (coming soon)'];
    public static function register(): void { if (!self::local()) return; add_rewrite_rule('^community/new/?$', 'index.php?tnet_community_topic_composer=1', 'top'); add_filter('query_vars', static function (array $vars): array { $vars[]='tnet_community_topic_composer'; return $vars; }); add_action('template_redirect', [self::class,'render']); }
    private static function local(): bool { return defined('DDEV_PROJECT') || (bool)getenv('DDEV_PROJECT'); }
    public static function render(): void { if (!get_query_var('tnet_community_topic_composer')) return; if (!is_user_logged_in() || !current_user_can('read')) auth_redirect(); if ('POST'===strtoupper($_SERVER['REQUEST_METHOD']??'')) self::submit(); self::form([]); exit; }
    private static function submit(): void {
        if (!isset($_POST['tnet_topic_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tnet_topic_nonce'])), 'tnet_community_topic')) self::form(['Nonce verification failed. Please try again.']);
        $community=sanitize_text_field(wp_unslash($_POST['community_id']??'')); $submission_id=sanitize_text_field(wp_unslash($_POST['submission_id']??'')) ?: 'web-'.wp_generate_uuid4(); $title=sanitize_text_field(wp_unslash($_POST['title']??'')); $body=sanitize_textarea_field(wp_unslash($_POST['body']??'')); $post_mode=sanitize_key(wp_unslash($_POST['post_mode']??'discussion')); $link_url=esc_url_raw(wp_unslash($_POST['link_url']??''));
        $errors=[]; if (!isset(self::COMMUNITIES[$community])) $errors[]='Choose a valid Community.'; if ($title==='') $errors[]='Enter a topic title.'; if ($body==='') $errors[]='Enter the topic body.'; if (!isset(self::MODES[$post_mode])) $post_mode='discussion'; if ($errors) self::form($errors, compact('community','submission_id','title','body','post_mode','link_url'));
        $draft=['submission_id'=>$submission_id,'community_id'=>$community,'author_id'=>'user:'.(int)get_current_user_id(),'post_type'=>'topic','title'=>$title,'body'=>$body,'parent_post_id'=>null,'visibility'=>'public','publication_mode'=>'post_first','moderation_input'=>'clear','compatibility_refs'=>['composer'=>['post_mode'=>$post_mode,'attachments'=>[],'links'=>$link_url!==''?[['url'=>$link_url,'enrichment'=>'deferred']]:[]]],'audit_context'=>['source'=>'local-topic-composer']];
        $result=(new TNet_Community_Publisher_Application())->publish_and_persist($draft,self::COMMUNITIES,['actor_id'=>$draft['author_id']]); if (empty($result['accepted'])||empty($result['post']['post_id'])) self::form(['The topic could not be published. Please try again.'],compact('community','submission_id','title','body','post_mode','link_url')); $path=str_replace('%3A',':',rawurlencode($result['post']['post_id'])); wp_safe_redirect(home_url('/community/thread/'.$path.'/')); exit;
    }
    private static function form(array $errors,array $values=[]): void {
        status_header(200); nocache_headers(); header('X-Robots-Tag: noindex, nofollow'); $community=$values['community']??$values['community_id']??'community:local-demo'; $submission_id=$values['submission_id']??'web-'.wp_generate_uuid4(); $title=$values['title']??''; $body=$values['body']??''; $post_mode=$values['post_mode']??'discussion'; $link_url=$values['link_url']??'';
        echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Start a Discussion | Teachers.Net</title><style>body{font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.5;color:#1d2327}main{border:1px solid #ccd0d4;border-radius:8px;padding:clamp(1rem,4vw,2rem)}label{display:block;font-weight:600;margin:.9rem 0 .35rem}input,select,textarea{box-sizing:border-box;width:100%;border:1px solid #8c8f94;border-radius:4px;padding:.65rem;font:inherit}textarea{min-height:12rem;resize:vertical}.composer-section{border-top:1px solid #dcdcde;margin-top:1.25rem;padding-top:1rem}.composer-section h2{font-size:1.05rem;margin:0 0 .35rem}.hint{color:#646970;font-size:.92rem}.attachment-empty{border:1px dashed #8c8f94;border-radius:6px;padding:1rem;background:#f6f7f7}.attachment-actions{display:flex;gap:.5rem;flex-wrap:wrap}.secondary{background:#fff!important;color:#135e96!important;border:1px solid #135e96!important}.actions{display:flex;gap:1rem;align-items:center;margin-top:1.25rem}button{background:#135e96;color:#fff;border:0;border-radius:4px;padding:.7rem 1rem;font:inherit;font-weight:600;cursor:pointer}.back{color:#135e96}.errors{border-left:4px solid #b32d2e;background:#fcf0f1;padding:.75rem 1rem}.errors li+li{margin-top:.3rem}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #1d70b8;outline-offset:2px}@media(max-width:520px){.actions{align-items:stretch;flex-direction:column}}</style></head><body><main><p><a class="back" href="'.esc_url(home_url('/community/')).'">← Community</a></p><h1>Start a Discussion</h1><p>Share a question or idea with the Community.</p>';
        if ($errors) { echo '<div class="errors" role="alert"><ul>'; foreach($errors as $error) echo '<li>'.esc_html($error).'</li>'; echo '</ul></div>'; }
        echo '<form method="post">'.wp_nonce_field('tnet_community_topic','tnet_topic_nonce',true,false).'<input type="hidden" name="submission_id" value="'.esc_attr($submission_id).'" /><section class="composer-section" aria-labelledby="context-heading"><h2 id="context-heading">Where should this go?</h2><label for="community_id">Community</label><select id="community_id" name="community_id">'; foreach(self::COMMUNITIES as $id=>$label) echo '<option value="'.esc_attr($id).'"'.selected($community,$id,false).'>'.esc_html($label).'</option>'; echo '</select><label for="post_mode">Post type</label><select id="post_mode" name="post_mode">'; foreach(self::MODES as $mode=>$label) echo '<option value="'.esc_attr($mode).'"'.selected($post_mode,$mode,false).'>'.esc_html($label).'</option>'; echo '</select></section><section class="composer-section" aria-labelledby="writing-heading"><h2 id="writing-heading">Write your post</h2><label for="title">Title</label><input id="title" name="title" type="text" value="'.esc_attr($title).'" required><label for="body">Body</label><textarea id="body" name="body" required aria-describedby="body-help">'.esc_textarea($body).'</textarea><p id="body-help" class="hint">Plain text is supported now. Rich formatting will be added later.</p></section><details class="composer-section"><summary><strong>Add to your post</strong></summary><p class="hint">Advanced attachments are progressively disclosed and ready for future media families.</p><fieldset class="attachment-empty"><legend>Attachments</legend><p>No files attached.</p><div class="attachment-actions"><button class="secondary" type="button" disabled aria-disabled="true">Add image (coming soon)</button><button class="secondary" type="button" disabled aria-disabled="true">Add document (coming soon)</button></div></fieldset><label for="link_url">Link attachment</label><input id="link_url" name="link_url" type="url" value="'.esc_attr($link_url).'" placeholder="https://example.com" aria-describedby="link-help"><p id="link-help" class="hint">The link is stored as an attachment reference. Preview enrichment is not enabled.</p></details><div class="actions"><button type="submit">Publish Topic</button><a class="back" href="'.esc_url(home_url('/community/')).'">Cancel</a></div></form></main></body></html>';
    }
}
